INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`, `VerifiedBuild`) VALUES
(84002, 'frFR', 'Ezh’ra, Voix du Tonnerre', 'Un bâton ancestral chargé de l’écho des tempêtes. À chaque incantation, le tonnerre répond.', 0),
(84002, 'deDE', 'Ezh’ra, Stimme des Donners', 'Ein Stab der Ahnen, geladen mit dem Widerhall der Stürme. Auf jede Beschwörungsformel antwortet der Donner.', 0),
(84002, 'esES', 'Ezh’ra, voz del trueno', 'Un bastón ancestral cargado con el eco de las tormentas. Con cada conjuro, el trueno responde.', 0),
(84002, 'ruRU', 'Эж’ра, глас грома', 'Посох предков, заряженный эхом бурь. На каждое заклинание ему отвечает гром.', 0),
(84003, 'frFR', 'Nairūn, Souffle des Anciens', 'Un souffle apaisant traverse ce bâton. À son passage, les blessures se referment, et les esprits murmurent la paix.', 0),
(84003, 'deDE', 'Nairūn, Atem der Uralten', 'Ein besänftigender Atem durchströmt diesen Stab. Wo er vorüberzieht, schließen sich Wunden, und die Geister flüstern von Frieden.', 0),
(84003, 'esES', 'Nairūn, aliento de los Ancestros', 'Un aliento sosegador recorre este bastón. A su paso, las heridas se cierran y los espíritus susurran paz.', 0),
(84003, 'ruRU', 'Найрун, дыхание Древних', 'Сквозь этот посох струится умиротворяющее дыхание. Там, где оно проходит, раны затягиваются, а духи шепчут о мире.', 0),
(84004, 'frFR', 'Kelrah, Harmonie des Éléments', 'Né de la confluence des quatre forces primordiales, ce bouclier équilibre feu, eau, air et terre pour apaiser, protéger et restaurer.', 0),
(84004, 'deDE', 'Kelrah, Harmonie der Elemente', 'Geboren aus dem Zusammenfluss der vier Urkräfte, bringt dieser Schild Feuer, Wasser, Luft und Erde ins Gleichgewicht, um zu besänftigen, zu schützen und wiederherzustellen.', 0),
(84004, 'esES', 'Kelrah, armonía de los elementos', 'Nacido de la confluencia de las cuatro fuerzas primordiales, este escudo equilibra fuego, agua, aire y tierra para calmar, proteger y restaurar.', 0),
(84004, 'ruRU', 'Келра, гармония стихий', 'Рожденный слиянием четырех первозданных сил, этот щит уравновешивает огонь, воду, воздух и землю, чтобы успокаивать, защищать и исцелять.', 0),
(84005, 'frFR', 'Drokhan, Poing des Tempêtes', 'Chaque coup porté avec Drokhan libère la fureur des éléments. Le feu gronde, la foudre danse, la terre cède.', 0),
(84005, 'deDE', 'Drokhan, Faust der Stürme', 'Jeder Schlag mit Drokhan entfesselt den Zorn der Elemente. Das Feuer tost, Blitze tanzen, die Erde gibt nach.', 0),
(84005, 'esES', 'Drokhan, puño de las tormentas', 'Cada golpe asestado con Drokhan desata la furia de los elementos. El fuego ruge, los relámpagos danzan, la tierra cede.', 0),
(84005, 'ruRU', 'Дрохан, кулак бурь', 'Каждый удар Дрохана высвобождает ярость стихий. Ревет пламя, пляшут молнии, земля уходит из-под ног.', 0),
(84006, 'frFR', 'Mak\'hor, Frappe des Esprits', 'Cette arme résonne à chaque impact du chant des ancêtres. Elle guide la main du chaman avec la force des éléments incarnés.', 0),
(84006, 'deDE', 'Mak\'hor, Schlag der Geister', 'Mit jedem Einschlag hallt in dieser Waffe das Lied der Ahnen wider. Sie führt die Hand des Schamanen mit der Kraft der fleischgewordenen Elemente.', 0),
(84006, 'esES', 'Mak\'hor, golpe de los espíritus', 'Con cada impacto, esta arma resuena con el canto de los ancestros. Guía la mano del chamán con la fuerza de los elementos hechos carne.', 0),
(84006, 'ruRU', 'Мак\'хор, удар духов', 'С каждым ударом это оружие откликается песнью предков. Оно направляет руку шамана силой воплощенных стихий.', 0),
(84007, 'frFR', 'Kael’Thorr, Hurlement Sanglant', 'Créé pour abattre sans pitié, cet arc déchire l’air comme un cri de guerre. Chaque flèche cherche le cœur. Chaque tir réclame du sang.', 0),
(84007, 'deDE', 'Kael’Thorr, Blutiges Geheul', 'Geschaffen, um gnadenlos niederzustrecken, zerreißt dieser Bogen die Luft wie ein Kriegsschrei. Jeder Pfeil sucht das Herz. Jeder Schuss verlangt nach Blut.', 0),
(84007, 'esES', 'Kael’Thorr, aullido sangriento', 'Hecho para abatir sin piedad, este arco desgarra el aire como un grito de guerra. Cada flecha busca el corazón. Cada disparo exige sangre.', 0),
(84007, 'ruRU', 'Кель’Торр, кровавый вой', 'Созданный, чтобы разить без пощады, этот лук разрывает воздух, словно боевой клич. Каждая стрела ищет сердце. Каждый выстрел требует крови.', 0),
(84008, 'frFR', 'Xer’thul, Maître des Chaînes', 'Les âmes liées à ce sceptre ne hurlent plus — elles obéissent. Chaque sort lancé est un ordre, chaque cible une offrande.', 0),
(84008, 'deDE', 'Xer’thul, Meister der Ketten', 'Die an dieses Zepter gebundenen Seelen schreien nicht mehr — sie gehorchen. Jeder gewirkte Zauber ist ein Befehl, jedes Ziel eine Opfergabe.', 0),
(84008, 'esES', 'Xer’thul, señor de las cadenas', 'Las almas atadas a este cetro ya no gritan: obedecen. Cada hechizo lanzado es una orden; cada objetivo, una ofrenda.', 0),
(84008, 'ruRU', 'Ксер’тул, повелитель цепей', 'Души, скованные этим скипетром, больше не кричат — они повинуются. Каждое заклинание — приказ, каждая цель — подношение.', 0),
(84009, 'frFR', 'Varkhal, Lame du Silence Glacé', 'Forgée dans un tombeau de givre éternel, cette lame ne chante pas en frappant : elle fait taire. À son contact, le sang se fige avant de couler.', 0),
(84009, 'deDE', 'Varkhal, Klinge der gefrorenen Stille', 'Geschmiedet in einer Gruft ewigen Frosts, singt diese Klinge nicht, wenn sie zuschlägt: Sie bringt zum Schweigen. Bei ihrer Berührung gefriert das Blut, bevor es fließen kann.', 0),
(84009, 'esES', 'Varkhal, hoja del silencio helado', 'Forjada en una tumba de escarcha eterna, esta hoja no canta al golpear: silencia. A su contacto, la sangre se congela antes de poder fluir.', 0),
(84009, 'ruRU', 'Вархал, клинок ледяного безмолвия', 'Выкованный в гробнице вечной мерзлоты, этот клинок не поет, когда разит: он заставляет умолкнуть. От его прикосновения кровь застывает, не успев пролиться.', 0),
(84010, 'frFR', 'Skorrn, Morsure de l’Hiver Noir', 'Chaque entaille de Skorrn vole la chaleur du corps. La chair se craquèle, le givre s’infiltre, et la mort s’installe sans un bruit.', 0),
(84010, 'deDE', 'Skorrn, Biss des Schwarzen Winters', 'Jeder Schnitt von Skorrn raubt dem Körper die Wärme. Das Fleisch reißt auf, der Frost sickert ein, und der Tod hält lautlos Einzug.', 0),
(84010, 'esES', 'Skorrn, mordedura del Invierno negro', 'Cada corte de Skorrn roba el calor del cuerpo. La carne se agrieta, la escarcha se filtra y la muerte se instala sin hacer ruido.', 0),
(84010, 'ruRU', 'Скоррн, укус Черной зимы', 'Каждый порез Скоррна крадет тепло тела. Плоть трескается, иней проникает внутрь, и смерть беззвучно вступает в свои права.', 0),
(84011, 'frFR', 'Vorthalak, Fléau des Vivants', 'Chaque coup porté infecte, chaque plaie ouverte pourrit. Vorthalak ne cherche pas à tuer rapidement, il appelle la chair à se trahir...', 0),
(84011, 'deDE', 'Vorthalak, Geißel der Lebenden', 'Jeder Schlag infiziert, jede offene Wunde fault. Vorthalak will nicht schnell töten, sondern ruft das Fleisch dazu auf, sich selbst zu verraten...', 0),
(84011, 'esES', 'Vorthalak, azote de los vivos', 'Cada golpe infecta, cada herida abierta se pudre. Vorthalak no busca matar deprisa; llama a la carne a traicionarse a sí misma...', 0),
(84011, 'ruRU', 'Ворталак, бич живых', 'Каждый удар заражает, каждая открытая рана гниет. Ворталак не стремится убить быстро: он призывает плоть предать саму себя...', 0),
(84012, 'frFR', 'Drethmâr, Trône de Sang', 'On raconte qu’elle ne repose jamais à terre : là où elle chute, la terre saigne. Le porteur n’a pas besoin d’armure, il se dresse, nourri par chaque coup reçu. Ceux qui l’affrontent s’épuisent. Lui, non.', 0),
(84012, 'deDE', 'Drethmâr, Thron des Blutes', 'Man sagt, diese Waffe ruhe niemals am Boden: Wo sie niederfällt, blutet die Erde. Ihr Träger braucht keine Rüstung; er steht aufrecht, genährt von jedem Schlag, den er einsteckt. Wer sich ihm stellt, erschöpft sich. Er nicht.', 0),
(84012, 'esES', 'Drethmâr, trono de sangre', 'Se dice que nunca descansa en el suelo: donde cae, la tierra sangra. Su portador no necesita armadura; se mantiene erguido, alimentado por cada golpe que recibe. Quienes se enfrentan a él se agotan. Él no.', 0),
(84012, 'ruRU', 'Дретмар, трон крови', 'Говорят, оно никогда не лежит на земле: там, куда оно падает, земля истекает кровью. Его владельцу не нужна броня — он стоит непоколебимо, питаясь каждым полученным ударом. Те, кто выходит против него, выбиваются из сил. Он — нет.', 0),
(84013, 'frFR', 'Elun\'dor, Voix des Cieux Silencieux', 'Les Anciens disent que ce bâton n’a pas été façonné mais semé. Lorsque le vent se tait et que les feuilles cessent de bouger, on peut entendre les étoiles parler à travers lui.', 0),
(84013, 'deDE', 'Elun\'dor, Stimme der schweigenden Himmel', 'Die Uralten sagen, dieser Stab sei nicht geformt, sondern gesät worden. Wenn der Wind verstummt und die Blätter sich nicht mehr regen, kann man die Sterne durch ihn sprechen hören.', 0),
(84013, 'esES', 'Elun\'dor, voz de los cielos silenciosos', 'Los Ancestros dicen que este bastón no fue tallado, sino sembrado. Cuando el viento calla y las hojas dejan de moverse, se puede oír a las estrellas hablar a través de él.', 0),
(84013, 'ruRU', 'Элун\'дор, глас безмолвных небес', 'Древние говорят, что этот посох не вырезали, а посеяли. Когда ветер стихает и листья замирают, можно услышать, как сквозь него говорят звезды.', 0),
(84014, 'frFR', 'Liora, Berceuse des Racines', 'Là où elle touche, la sève circule à nouveau. Chaque blessure devient terre, chaque douleur une fleur.', 0),
(84014, 'deDE', 'Liora, Wiegenlied der Wurzeln', 'Wo immer Liora berührt, fließt der Saft aufs Neue. Jede Wunde wird zu Erde, jeder Schmerz zu einer Blume.', 0),
(84014, 'esES', 'Liora, nana de las raíces', 'Allí donde toca, la savia vuelve a fluir. Cada herida se convierte en tierra; cada dolor, en una flor.', 0),
(84014, 'ruRU', 'Лиора, колыбельная корней', 'Где бы она ни коснулась, вновь бежит древесный сок. Каждая рана становится землей, каждая боль — цветком.', 0),
(84015, 'frFR', 'Tharnok, Échine du Monde', 'Elle ne plie pas. Elle ne rompt pas. Elle encaisse, encore et encore, jusqu’à ce que l’ennemi oublie pourquoi il frappait.', 0),
(84015, 'deDE', 'Tharnok, Rückgrat der Welt', 'Es beugt sich nicht. Es bricht nicht. Es steckt die Schläge ein, immer und immer wieder, bis der Feind vergisst, warum er zuschlug.', 0),
(84015, 'esES', 'Tharnok, espinazo del mundo', 'No se dobla. No se rompe. Encaja los golpes, una y otra vez, hasta que el enemigo olvida por qué golpeaba.', 0),
(84015, 'ruRU', 'Тарнок, хребет мира', 'Он не гнется. Он не ломается. Он принимает удары — снова и снова, — пока враг не забудет, зачем бил.', 0),
(84016, 'frFR', 'Brakk, Fracture Totale', 'Ce n’est pas une arme. C’est un verdict. Elle ne tranche pas. Elle casse. Os, cuirasse ou muraille. Pas de distinction.', 0),
(84016, 'deDE', 'Brakk, Totaler Bruch', 'Dies ist keine Waffe. Es ist ein Urteil. Es schneidet nicht. Es bricht. Knochen, Brustplatte oder Mauer. Kein Unterschied.', 0),
(84016, 'esES', 'Brakk, fractura total', 'Esto no es un arma. Es un veredicto. No corta. Rompe. Hueso, coraza o muralla. Sin distinción.', 0),
(84016, 'ruRU', 'Бракк, полный перелом', 'Это не оружие. Это приговор. Он не режет. Он ломает. Кость, кираса или стена. Без разбора.', 0),
(84017, 'frFR', 'Drakthor, Le Brise-Écaille', 'Son éclat écarlate inspire la terreur aux plus anciens Wyrms et son tranchant peut fendre les écailles de Deathwing.', 0),
(84017, 'deDE', 'Drakthor, der Schuppenbrecher', 'Sein scharlachroter Glanz versetzt die ältesten Wyrms in Angst und Schrecken, und seine Schneide vermag die Schuppen von Todesschwinge zu spalten.', 0),
(84017, 'esES', 'Drakthor, el rompescamas', 'Su brillo escarlata infunde terror a los vermis más antiguos, y su filo puede partir las escamas de Alamuerte.', 0),
(84017, 'ruRU', 'Драктор, сокрушитель чешуи', 'Его алый блеск вселяет ужас в древнейших змеев, а его лезвие способно рассечь чешую Смертокрыла.', 0),
(84018, 'frFR', 'Malthen, Égide éternelle', 'Ses runes de protection ancestrales repoussent magie noire et fureur démoniaque, transformant son porteur en forteresse vivante que nul ne peut briser.', 0),
(84018, 'deDE', 'Malthen, Ewige Aegis', 'Ihre uralten Schutzrunen wehren dunkle Magie und dämonischen Zorn ab und verwandeln ihren Träger in eine lebende Festung, die niemand brechen kann.', 0),
(84018, 'esES', 'Malthen, égida eterna', 'Sus ancestrales runas de protección repelen la magia oscura y la furia demoníaca, y convierten a su portador en una fortaleza viviente que nadie puede quebrar.', 0),
(84018, 'ruRU', 'Малтен, вечная эгида', 'Его древние защитные руны отражают темную магию и демоническую ярость, превращая владельца в живую крепость, которую никому не сокрушить.', 0),
(84019, 'frFR', 'Vaelthis, Brise-sortilège', 'Son pouvoir consume les sorts les plus puissants et réduit en cendres quiconque ose défier son porteur.', 0),
(84019, 'deDE', 'Vaelthis, Zauberbrecher', 'Seine Macht verzehrt die mächtigsten Zauber und legt jeden in Asche, der es wagt, seinem Träger zu trotzen.', 0),
(84019, 'esES', 'Vaelthis, rompedor de hechizos', 'Su poder consume los hechizos más poderosos y reduce a cenizas a quien ose desafiar a su portador.', 0),
(84019, 'ruRU', 'Вельтис, чаролом', 'Его сила поглощает самые могущественные заклинания и обращает в пепел любого, кто осмелится бросить вызов его владельцу.', 0),
(84020, 'frFR', 'Ashbringer, Fléau des morts', 'Son éclat divin a anéanti des armées entières de morts-vivants et son simple nom fait trembler les plus puissants. Aucune créature impie ne peut survivre à son contact.', 0),
(84020, 'deDE', 'Aschenbringer, Verderben der Toten', 'Sein göttlicher Glanz hat ganze Armeen von Untoten vernichtet, und schon sein Name lässt die Mächtigsten erzittern. Keine unheilige Kreatur überlebt seine Berührung.', 0),
(84020, 'esES', 'Crematoria, perdición de los muertos', 'Su resplandor divino ha aniquilado ejércitos enteros de no-muertos, y su mero nombre hace temblar a los más poderosos. Ninguna criatura profana puede sobrevivir a su contacto.', 0),
(84020, 'ruRU', 'Испепелитель, погибель мертвых', 'Его божественное сияние уничтожило целые армии нежити, а одно лишь его имя заставляет трепетать сильнейших. Ни одно нечестивое создание не переживет его прикосновения.', 0),
(84021, 'frFR', 'Vindictus, Châtiment-ardent', 'Cette masse sacrée pulse d\'une fureur divine qui punit instantanément ceux qui osent menacer les justes. Son feu céleste brûle les âmes corrompues et sa justice implacable transforme la défense en vengeance purificatrice.', 0),
(84021, 'deDE', 'Vindictus, Brennende Vergeltung', 'Dieser heilige Streitkolben pulsiert vor göttlichem Zorn, der jeden sofort bestraft, der es wagt, die Gerechten zu bedrohen. Sein himmlisches Feuer verbrennt verderbte Seelen, und seine unerbittliche Gerechtigkeit verwandelt Verteidigung in läuternde Rache.', 0),
(84021, 'esES', 'Vindictus, reprensión ardiente', 'Esta maza sagrada palpita con una furia divina que castiga al instante a quienes osan amenazar a los justos. Su fuego celestial quema las almas corruptas, y su implacable justicia convierte la defensa en venganza purificadora.', 0),
(84021, 'ruRU', 'Виндиктус, пылающее воздаяние', 'Эта священная булава пульсирует божественной яростью, мгновенно карающей тех, кто смеет угрожать праведным. Ее небесный огонь сжигает оскверненные души, а неумолимое правосудие превращает защиту в очищающее возмездие.', 0),
(84022, 'frFR', 'Salvation, Égide de Sanctuaire', 'Ce bouclier consacré émane une aura de protection céleste baignant les alliés dans une grâce divine.', 0),
(84022, 'deDE', 'Rettung, Aegis des Heiligtums', 'Dieser geweihte Schild verströmt eine Aura himmlischen Schutzes und taucht Verbündete in göttliche Gnade.', 0),
(84022, 'esES', 'Salvación, égida del santuario', 'Este escudo consagrado irradia un aura de protección celestial que baña a los aliados en gracia divina.', 0),
(84022, 'ruRU', 'Спасение, эгида святилища', 'Этот освященный щит излучает ауру небесной защиты, омывая союзников божественной благодатью.', 0),
(84023, 'frFR', 'Solareth, Souffle-de-vie', 'Forgée par les anges eux-mêmes, elle peut ramener les mourants du seuil de la mort et ses bénédictions divines guérissent même les malédictions les plus anciennes.', 0),
(84023, 'deDE', 'Solareth, Atem des Lebens', 'Von den Engeln selbst geschmiedet, vermag diese Waffe die Sterbenden von der Schwelle des Todes zurückzuholen, und ihre göttlichen Segnungen heilen selbst die ältesten Flüche.', 0),
(84023, 'esES', 'Solareth, aliento de vida', 'Forjada por los mismísimos ángeles, puede traer de vuelta a los moribundos desde el umbral de la muerte, y sus bendiciones divinas curan incluso las maldiciones más antiguas.', 0),
(84023, 'ruRU', 'Соларет, дыхание жизни', 'Выкованное самими ангелами, оно способно вернуть умирающих с порога смерти, а его божественные благословения исцеляют даже самые древние проклятия.', 0),
(84024, 'frFR', 'Kyresion, Rempart du Juste', 'En présence de Kyresion, les plaies se referment et les âmes sont apaisées.', 0),
(84024, 'deDE', 'Kyresion, Bollwerk der Gerechten', 'In Kyresions Gegenwart schließen sich Wunden und Seelen finden Ruhe.', 0),
(84024, 'esES', 'Kyresion, baluarte de los justos', 'En presencia de Kyresion, las heridas se cierran y las almas se sosiegan.', 0),
(84024, 'ruRU', 'Кирезион, оплот праведных', 'В присутствии Кирезиона раны затягиваются, а души обретают покой.', 0),
(84025, 'frFR', 'Sha\'haggul, Voix des tourments', 'Il murmure constamment des secrets interdits qui brisent l\'esprit des ennemis. Ses tentacules d\'ombre s\'enroulent autour des âmes faibles, les plongeant dans une folie dévorante où seules résonnent les voix du Vide.', 0),
(84025, 'deDE', 'Sha\'haggul, Stimme der Qualen', 'Sha\'haggul flüstert unablässig verbotene Geheimnisse, die den Verstand der Feinde zerschmettern. Seine schattenhaften Tentakel winden sich um schwache Seelen und stürzen sie in einen verzehrenden Wahnsinn, in dem nur die Stimmen der Leere widerhallen.', 0),
(84025, 'esES', 'Sha\'haggul, voz de los tormentos', 'Susurra sin cesar secretos prohibidos que destrozan la mente de los enemigos. Sus tentáculos sombríos se enroscan en torno a las almas débiles y las sumen en una locura devoradora donde solo resuenan las voces del Vacío.', 0),
(84025, 'ruRU', 'Ша\'хаггул, глас мучений', 'Он непрестанно нашептывает запретные тайны, разрушающие разум врагов. Его теневые щупальца обвивают слабые души, ввергая их во всепоглощающее безумие, где звучат лишь голоса Бездны.', 0),
(84026, 'frFR', 'Luminaris, Bénédiction éternelle', 'Sa lumière dorée restaure instantanément la vie et l\'espoir, capable de guérir n\'importe quelle blessure et de purifier les âmes les plus souillées par ses bénédictions infinies.', 0),
(84026, 'deDE', 'Luminaris, Ewiger Segen', 'Sein goldenes Licht stellt augenblicklich Leben und Hoffnung wieder her, vermag jede Wunde zu heilen und mit seinen unendlichen Segnungen selbst die besudeltsten Seelen zu läutern.', 0),
(84026, 'esES', 'Luminaris, bendición eterna', 'Su luz dorada restaura al instante la vida y la esperanza, capaz de curar cualquier herida y de purificar las almas más mancilladas con sus bendiciones infinitas.', 0),
(84026, 'ruRU', 'Люминарис, вечное благословение', 'Его золотой свет мгновенно возвращает жизнь и надежду: своими бесконечными благословениями он способен исцелить любую рану и очистить самые оскверненные души.', 0),
(84027, 'frFR', 'Sanguineus, la silencieuse', 'Sa lame affûtée comme un rasoir trouve toujours les points vitaux, et son manche taillé dans l\'os permet des frappes furtives d\'une précision mortelle.', 0),
(84027, 'deDE', 'Sanguineus, der Lautlose', 'Seine rasiermesserscharfe Klinge findet stets die lebenswichtigen Stellen, und sein aus Knochen geschnitzter Griff erlaubt verstohlene Hiebe von tödlicher Präzision.', 0),
(84027, 'esES', 'Sanguineus, la silenciosa', 'Su hoja, afilada como una navaja, siempre encuentra los puntos vitales, y su empuñadura tallada en hueso permite golpes sigilosos de una precisión mortal.', 0),
(84027, 'ruRU', 'Сангвиней, безмолвный', 'Его острый как бритва клинок всегда находит уязвимые места, а вырезанная из кости рукоять позволяет наносить скрытные удары смертоносной точности.', 0),
(84028, 'frFR', 'Carnifex, la pernicieuse', 'Cette dague maudite boit le sang de ses victimes et ne laisse jamais de traces. Chaque coup fatal nourrit sa soif insatiable, et sa lame empoisonnée transforme les assassinats en boucheries silencieuses où seuls les gémissements d\'agonie résonnent.', 0),
(84028, 'deDE', 'Carnifex, der Unheilvolle', 'Dieser verfluchte Dolch trinkt das Blut seiner Opfer und hinterlässt niemals eine Spur. Jeder tödliche Stoß nährt seinen unstillbaren Durst, und seine vergiftete Klinge verwandelt Meuchelmorde in lautlose Gemetzel, in denen einzig das Stöhnen der Todesqual widerhallt.', 0),
(84028, 'esES', 'Carnifex, la perniciosa', 'Esta daga maldita bebe la sangre de sus víctimas y nunca deja rastro. Cada golpe mortal alimenta su sed insaciable, y su hoja envenenada convierte los asesinatos en carnicerías silenciosas donde solo resuenan los gemidos de agonía.', 0),
(84028, 'ruRU', 'Карнифекс, пагубный', 'Этот проклятый кинжал пьет кровь своих жертв и никогда не оставляет следов. Каждый смертельный удар утоляет его ненасытную жажду, а отравленный клинок превращает убийства в безмолвную бойню, где звучат лишь предсмертные стоны.', 0),
(84029, 'frFR', 'Shuor\'ror, Crépuscule du savoir', 'Tranche, coupe et massacre - il ne reste qu\'un sillon de sang et de boyaux. Cette lame n\'a jamais connu le repos contrairement à ses ennemis.', 0),
(84029, 'deDE', 'Shuor\'ror, Zwielicht des Wissens', 'Schneiden, schlitzen und schlachten — zurück bleibt nur eine Spur aus Blut und Eingeweiden. Anders als ihre Feinde hat diese Klinge nie Ruhe gekannt.', 0),
(84029, 'esES', 'Shuor\'ror, ocaso del saber', 'Rebana, corta y masacra: no queda más que un rastro de sangre y vísceras. A diferencia de sus enemigos, esta hoja nunca ha conocido el descanso.', 0),
(84029, 'ruRU', 'Шуор\'рор, сумерки знания', 'Резать, рубить, кромсать — после него остается лишь след из крови и внутренностей. В отличие от своих врагов, этот клинок никогда не знал покоя.', 0),
(84030, 'frFR', 'Shuadslayern, Aube de l\'oubli', 'Ses victimes ne portaient pas d\'armures et un coup suffisait à les réduire au silence.', 0),
(84030, 'deDE', 'Shuadslayern, Morgengrauen des Vergessens', 'Die Opfer dieser Klinge trugen keine Rüstung, und ein einziger Hieb genügte, um sie zum Schweigen zu bringen.', 0),
(84030, 'esES', 'Shuadslayern, alba del olvido', 'Sus víctimas no llevaban armadura, y bastaba un solo golpe para silenciarlas.', 0),
(84030, 'ruRU', 'Шуадслейерн, рассвет забвения', 'Его жертвы не носили доспехов, и одного удара хватало, чтобы заставить их умолкнуть.', 0),
(84031, 'frFR', 'Vorgath, plaie des dragons', '« J’ai vu cette épée planter un drake comme une tente dans la boue. Il a craché, hurlé, brûlé... mais il n’a pas bougé. Quand tu tiens Vorgath, c’est pas toi qui la manies. C’est elle qui décide quand le combat est fini. »', 0),
(84031, 'deDE', 'Vorgath, Verderben der Drachen', '„Ich hab gesehen, wie dieses Schwert einen Drachen wie ein Zelt in den Schlamm genagelt hat. Er hat gespuckt, gebrüllt, gebrannt... aber er hat sich nicht gerührt. Wenn du Vorgath hältst, bist nicht du derjenige, der es führt. Es entscheidet, wann der Kampf vorbei ist.“', 0),
(84031, 'esES', 'Vorgath, perdición de los dragones', '«Vi esta espada clavar a un draco en el barro como si fuera una tienda de campaña. Escupió, rugió, quemó... pero no se movió. Cuando empuñas a Vorgath, no eres tú quien la blande. Es ella quien decide cuándo ha terminado el combate.»', 0),
(84031, 'ruRU', 'Воргат, погибель драконов', '«Видал я, как этот меч пригвоздил дракона к земле, будто колышек палатки в грязи. Тот плевался, ревел, жег... но с места не сдвинулся. Когда держишь Воргата, не ты им орудуешь. Он сам решает, когда бой окончен.»', 0),
(84032, 'frFR', 'Draemorr, Brise-Monde', 'Chaque coup est un séisme. Les montagnes se fendent, la terre cède, les océans s\'écartent. Elle ne gagne pas les batailles. Elle les efface.', 0),
(84032, 'deDE', 'Draemorr, Weltenbrecher', 'Jeder Schlag ist ein Erdbeben. Berge spalten sich, die Erde gibt nach, die Ozeane teilen sich. Diese Waffe gewinnt keine Schlachten. Sie löscht sie aus.', 0),
(84032, 'esES', 'Draemorr, rompemundos', 'Cada golpe es un terremoto. Las montañas se parten, la tierra cede, los océanos se abren. No gana batallas. Las borra.', 0),
(84032, 'ruRU', 'Дреморр, сокрушитель миров', 'Каждый удар — землетрясение. Горы раскалываются, земля разверзается, океаны расступаются. Он не выигрывает битвы. Он их стирает.', 0),
(84033, 'frFR', 'Aiguilles de l\'Aube', 'Nées du premier soleil, bénies par les anciens esprits. Chaque flèche perce l’ombre, chaque tir rappelle la lumière.', 0),
(84033, 'deDE', 'Nadeln der Morgendämmerung', 'Geboren aus der ersten Sonne, gesegnet von den uralten Geistern. Jeder Pfeil durchbohrt den Schatten, jeder Schuss ruft das Licht zurück.', 0),
(84033, 'esES', 'Agujas del alba', 'Nacidas del primer sol, bendecidas por los espíritus antiguos. Cada flecha atraviesa la sombra; cada disparo evoca la luz.', 0),
(84033, 'ruRU', 'Иглы рассвета', 'Рожденные первым солнцем, благословленные древними духами. Каждая стрела пронзает тьму, каждый выстрел напоминает о свете.', 0),
(84034, 'frFR', 'Crocs-de-Sang l\'Écorcheur', 'Il tranche, arrache, dépèce sans répit. Les cris de ses victimes se mêlent à ses dents jusqu\'à ce qu\'il ne reste que des morceaux.', 0),
(84034, 'deDE', 'Blutfang der Schinder', 'Er schneidet, reißt und schindet ohne Unterlass. Die Schreie seiner Opfer vermischen sich mit seinen Zähnen, bis nur noch Stücke übrig sind.', 0),
(84034, 'esES', 'Colmillo de sangre el Desollador', 'Rebana, desgarra y desuella sin descanso. Los gritos de sus víctimas se mezclan con sus dientes hasta que no quedan más que pedazos.', 0),
(84034, 'ruRU', 'Кровавый Клык Свежеватель', 'Он режет, рвет и свежует без передышки. Крики его жертв мешаются с его зубьями, пока от них не останутся одни клочья.', 0),
(84102, 'frFR', 'Bouquin abîmé par le froid', 'Les pages sont rigides, craquantes comme de la glace.', 0),
(84102, 'deDE', 'Frostgeschädigter Foliant', 'Die Seiten sind steif und knistern wie Eis.', 0),
(84102, 'esES', 'Tomo dañado por la escarcha', 'Las páginas están rígidas y crujen como el hielo.', 0),
(84102, 'ruRU', 'Поврежденный морозом фолиант', 'Страницы затвердели и хрустят, как лед.', 0),
(84103, 'frFR', 'Page gondolée par l’humidité', 'Fragile, prête à se réduire en poussière au moindre contact.', 0),
(84103, 'deDE', 'Von Feuchtigkeit gewellte Seite', 'Zerbrechlich, bereit, bei der leisesten Berührung zu Staub zu zerfallen.', 0),
(84103, 'esES', 'Página combada por la humedad', 'Frágil, a punto de deshacerse en polvo al menor roce.', 0),
(84103, 'ruRU', 'Покоробленная от сырости страница', 'Хрупкая, готова рассыпаться в прах от малейшего прикосновения.', 0),
(84104, 'frFR', 'Cahier effrité aux bords', 'Il ondule comme une vague figée.', 0),
(84104, 'deDE', 'An den Rändern zerbröselndes Notizbuch', 'Es wellt sich wie eine erstarrte Woge.', 0),
(84104, 'esES', 'Cuaderno desmenuzado por los bordes', 'Se ondula como una ola congelada.', 0),
(84104, 'ruRU', 'Тетрадь с осыпающимися краями', 'Ее листы изогнуты, словно застывшая волна.', 0),
(84105, 'frFR', 'Manuscrit mangé par les mites', 'Percé de petits trous, semblable à un tissu rongé.', 0),
(84105, 'deDE', 'Mottenzerfressenes Manuskript', 'Von winzigen Löchern durchsiebt, wie angenagter Stoff.', 0),
(84105, 'esES', 'Manuscrito apolillado', 'Plagado de diminutos agujeros, como una tela roída.', 0),
(84105, 'ruRU', 'Изъеденная молью рукопись', 'Испещрена крошечными дырочками, будто изъеденная ткань.', 0),
(84106, 'frFR', 'Volume couvert de poussière', 'À peine lisible sous une épaisse couche grise.', 0),
(84106, 'deDE', 'Staubbedeckter Band', 'Unter einer dicken grauen Schicht kaum lesbar.', 0),
(84106, 'esES', 'Volumen cubierto de polvo', 'Apenas legible bajo una gruesa capa gris.', 0),
(84106, 'ruRU', 'Запыленный том', 'Под толстым серым слоем едва можно что-то разобрать.', 0),
(84107, 'frFR', 'Livre à la reliure brisée', 'Son dos craque et laisse tomber des pages libres.', 0),
(84107, 'deDE', 'Buch mit gebrochenem Einband', 'Sein Rücken knackt und lässt lose Seiten herausfallen.', 0),
(84107, 'esES', 'Libro con la encuadernación rota', 'Su lomo cruje y deja caer páginas sueltas.', 0),
(84107, 'ruRU', 'Книга с порванным переплетом', 'Корешок трещит, и из книги выпадают отдельные листы.', 0),
(84108, 'frFR', 'Bouquin troué par la moisissure', 'Parsemé de taches sombres et de trous circulaires.', 0),
(84108, 'deDE', 'Von Schimmel zerfressener Foliant', 'Mit dunklen Flecken und kreisrunden Löchern übersät.', 0),
(84108, 'esES', 'Tomo plagado de moho', 'Salpicado de manchas oscuras y agujeros circulares.', 0),
(84108, 'ruRU', 'Фолиант, изъеденный плесенью', 'Усеян темными пятнами и круглыми дырами.', 0),
(84109, 'frFR', 'Parchemin craquelé', 'Dur et fissuré, comme une vieille peau asséchée.', 0),
(84109, 'deDE', 'Rissiges Pergament', 'Hart und zerfurcht wie alte, ausgetrocknete Haut.', 0),
(84109, 'esES', 'Pergamino agrietado', 'Duro y lleno de fisuras, como una vieja piel reseca.', 0),
(84109, 'ruRU', 'Потрескавшийся пергамент', 'Жесткий и растрескавшийся, как старая высохшая кожа.', 0),
(84110, 'frFR', 'Registre taché d’encre', 'Des coulures noires brouillent les lignes d’écriture.', 0),
(84110, 'deDE', 'Tintenbeflecktes Kontobuch', 'Schwarze Tropfen verwischen die geschriebenen Zeilen.', 0),
(84110, 'esES', 'Libro de cuentas manchado de tinta', 'Chorretones negros emborronan las líneas escritas.', 0),
(84110, 'ruRU', 'Заляпанная чернилами учетная книга', 'Черные потеки размывают написанные строки.', 0),
(84111, 'frFR', 'Carnet effacé par le soleil', 'L’encre pâle se dissipe, les mots deviennent fantômes.', 0),
(84111, 'deDE', 'Sonnengebleichtes Notizbuch', 'Die blasse Tinte verblasst; die Worte werden zu Geistern.', 0),
(84111, 'esES', 'Cuaderno descolorido por el sol', 'La tinta pálida se desvanece; las palabras se vuelven fantasmas.', 0),
(84111, 'ruRU', 'Выгоревшая на солнце записная книжка', 'Бледные чернила исчезают, слова превращаются в призраков.', 0),
(84112, 'frFR', 'Journal froissé et déchiré', 'Cabossé, aux pages froissées comme des cicatrices.', 0),
(84112, 'deDE', 'Zerknittertes, zerrissenes Tagebuch', 'Abgegriffen, die Seiten zerfurcht wie Narben.', 0),
(84112, 'esES', 'Diario arrugado y rasgado', 'Maltrecho, con las páginas surcadas de pliegues como cicatrices.', 0),
(84112, 'ruRU', 'Измятый, разорванный дневник', 'Потрепанный, страницы в заломах, словно в шрамах.', 0),
(84113, 'frFR', 'Livre rongé par l’humidité', 'Lourd, moisi, et collant entre les doigts.', 0),
(84113, 'deDE', 'Von Nässe zerfressenes Buch', 'Schwer, schimmlig und klebrig zwischen den Fingern.', 0),
(84113, 'esES', 'Libro carcomido por la humedad', 'Pesado, mohoso y pegajoso entre los dedos.', 0),
(84113, 'ruRU', 'Изъеденная сыростью книга', 'Тяжелая, заплесневелая и липкая на ощупь.', 0),
(84114, 'frFR', 'Feuille brûlée aux coins', 'Les bords noircis se réduisent en cendres.', 0),
(84114, 'deDE', 'An den Ecken verbranntes Blatt', 'Die geschwärzten Ränder zerfallen zu Asche.', 0),
(84114, 'esES', 'Hoja quemada por las esquinas', 'Los bordes ennegrecidos se deshacen en cenizas.', 0),
(84114, 'ruRU', 'Лист с обгоревшими углами', 'Почерневшие края рассыпаются в пепел.', 0),
(84115, 'frFR', 'Livre écorné', 'Les angles pliés trahissent un usage négligé.', 0),
(84115, 'deDE', 'Buch mit Eselsohren', 'Die umgeknickten Ecken verraten achtlosen Gebrauch.', 0),
(84115, 'esES', 'Libro con las esquinas dobladas', 'Las esquinas dobladas delatan un uso descuidado.', 0),
(84115, 'ruRU', 'Книга с загнутыми уголками', 'Загнутые уголки выдают небрежное обращение.', 0),
(84116, 'frFR', 'Volume oublié et moisi', 'Une odeur âcre émane de ses pages vertes de champignons.', 0),
(84116, 'deDE', 'Vergessener, schimmliger Band', 'Von seinen pilzgrünen Seiten steigt ein beißender Geruch auf.', 0),
(84116, 'esES', 'Volumen mohoso olvidado', 'Un olor acre emana de sus páginas, verdes de hongos.', 0),
(84116, 'ruRU', 'Забытый заплесневелый том', 'От его позеленевших от грибка страниц исходит едкий запах.', 0),
(84117, 'frFR', 'Page chiffonnée au sol', 'Froissée, marquée de traces de pas.', 0),
(84117, 'deDE', 'Zerknüllte Seite am Boden', 'Zerknittert und von Fußabdrücken gezeichnet.', 0),
(84117, 'esES', 'Página arrugada en el suelo', 'Arrugada, marcada con huellas de pisadas.', 0),
(84117, 'ruRU', 'Скомканная страница на земле', 'Смятая, со следами ног.', 0),
(84118, 'frFR', 'Lettre tachée de sang', 'L’encre s’est diluée en auréoles troubles.', 0),
(84118, 'deDE', 'Blutbefleckter Brief', 'Die Tinte ist zu trüben Rändern verlaufen.', 0),
(84118, 'esES', 'Carta manchada de sangre', 'La tinta se ha corrido formando cercos turbios.', 0),
(84118, 'ruRU', 'Окровавленное письмо', 'Чернила расплылись мутными кругами.', 0),
(84119, 'frFR', 'Enveloppe déchirée', 'Son contenu fragile est à moitié visible.', 0),
(84119, 'deDE', 'Zerrissener Umschlag', 'Sein zerbrechlicher Inhalt ist halb zu sehen.', 0),
(84119, 'esES', 'Sobre rasgado', 'Su frágil contenido se entrevé a medias.', 0),
(84119, 'ruRU', 'Разорванный конверт', 'Хрупкое содержимое наполовину выглядывает наружу.', 0),
(84120, 'frFR', 'Missive maculée de boue', 'Les mots sont noyés sous des éclaboussures brunâtres.', 0),
(84120, 'deDE', 'Schlammbespritztes Schreiben', 'Die Worte ertrinken unter bräunlichen Spritzern.', 0),
(84120, 'esES', 'Misiva salpicada de barro', 'Las palabras se ahogan bajo salpicaduras parduzcas.', 0),
(84120, 'ruRU', 'Забрызганное грязью послание', 'Слова тонут под бурыми брызгами.', 0),
(84121, 'frFR', 'Carton gondolé par la pluie', 'Lourd et mou, il ploie sous ses propres plis.', 0),
(84121, 'deDE', 'Vom Regen gewellter Karton', 'Schwer und weich sackt er unter seinen eigenen Falten zusammen.', 0),
(84121, 'esES', 'Cartón combado por la lluvia', 'Pesado y blando, se hunde bajo sus propios pliegues.', 0),
(84121, 'ruRU', 'Покоробленный от дождя картон', 'Тяжелый и размякший, он проседает под собственными складками.', 0),
(84122, 'frFR', 'Page déchirée', 'Des lambeaux pendent encore, battant au vent.', 0),
(84122, 'deDE', 'Zerrissene Seite', 'Noch hängen Fetzen daran, die im Wind flattern.', 0),
(84122, 'esES', 'Página rasgada', 'Aún le cuelgan jirones que ondean al viento.', 0),
(84122, 'ruRU', 'Порванная страница', 'С нее еще свисают клочья, трепещущие на ветру.', 0),
(84123, 'frFR', 'Brouillon gribouillé et raturé', 'Les lignes se croisent, griffonnées avec rage.', 0),
(84123, 'deDE', 'Bekritzelter, durchgestrichener Entwurf', 'Die Zeilen überkreuzen sich, im Zorn hingekritzelt.', 0),
(84123, 'esES', 'Borrador garabateado y tachado', 'Las líneas se entrecruzan, garabateadas con rabia.', 0),
(84123, 'ruRU', 'Исчерканный, перечеркнутый черновик', 'Строки, нацарапанные в ярости, налезают друг на друга.', 0),
(84124, 'frFR', 'Feuille effilochée', 'Ses fibres se détachent comme un tissu trop usé.', 0),
(84124, 'deDE', 'Ausgefranstes Blatt', 'Seine Fasern lösen sich wie abgetragener Stoff.', 0),
(84124, 'esES', 'Hoja deshilachada', 'Sus fibras se deshacen como una tela gastada.', 0),
(84124, 'ruRU', 'Обтрепанный лист', 'Его волокна расползаются, как изношенная ткань.', 0),
(84125, 'frFR', 'Signet effrité', 'Réduit à un mince fragment friable.', 0),
(84125, 'deDE', 'Zerbröselndes Lesezeichen', 'Zu einem dünnen, brüchigen Bruchstück zerfallen.', 0),
(84125, 'esES', 'Marcapáginas desmenuzado', 'Reducido a un fragmento fino y quebradizo.', 0),
(84125, 'ruRU', 'Рассыпающаяся закладка', 'От нее остался лишь тонкий ломкий обрывок.', 0),
(84126, 'frFR', 'Volume aux pages volantes', 'Il craque dès qu’on tente de le plier.', 0),
(84126, 'deDE', 'Band mit losen Seiten', 'Er knackt, sobald Ihr versucht, ihn zu falten.', 0),
(84126, 'esES', 'Volumen de páginas sueltas', 'Cruje en cuanto intentas doblarlo.', 0),
(84126, 'ruRU', 'Том из разрозненных листов', 'Он трещит при любой попытке его согнуть.', 0),
(84127, 'frFR', 'Lettre pourrie', 'Les plis mous portent la trace d’un long abandon.', 0),
(84127, 'deDE', 'Verrotteter Brief', 'Seine schlaffen Falten zeugen von langer Vernachlässigung.', 0),
(84127, 'esES', 'Carta podrida', 'Sus pliegues lacios llevan la marca de un largo abandono.', 0),
(84127, 'ruRU', 'Сгнившее письмо', 'Его обвисшие сгибы хранят следы долгого забвения.', 0),
(84128, 'frFR', 'Courrier à moitié effacé', 'Porte les marques de liquides oubliés.', 0),
(84128, 'deDE', 'Halb verblichener Brief', 'Er trägt die Spuren vergessener Flüssigkeiten.', 0),
(84128, 'esES', 'Carta medio borrada', 'Lleva las marcas de líquidos olvidados.', 0),
(84128, 'ruRU', 'Наполовину выцветшее письмо', 'На нем остались следы давно забытых жидкостей.', 0),
(84129, 'frFR', 'Parchemin détrempé', 'Les pages collées forment un bloc difforme.', 0),
(84129, 'deDE', 'Durchnässtes Pergament', 'Die verklebten Seiten bilden einen unförmigen Block.', 0),
(84129, 'esES', 'Pergamino empapado', 'Las páginas pegadas forman un bloque deforme.', 0),
(84129, 'ruRU', 'Промокший пергамент', 'Слипшиеся страницы образуют бесформенный ком.', 0),
(84130, 'frFR', 'Feuillet déchiré', 'Quasiment illisible.', 0),
(84130, 'deDE', 'Zerrissenes Flugblatt', 'Fast unleserlich.', 0),
(84130, 'esES', 'Folleto rasgado', 'Casi ilegible.', 0),
(84130, 'ruRU', 'Разорванная листовка', 'Почти не читается.', 0),
(84131, 'frFR', 'Page brûlée', 'Le feu a léché les lettres et englouti les bords, il ne reste quasiment plus rien.', 0),
(84131, 'deDE', 'Verbrannte Seite', 'Das Feuer hat an den Buchstaben geleckt und die Ränder verschlungen; fast nichts ist übrig.', 0),
(84131, 'esES', 'Página quemada', 'El fuego lamió las letras y devoró los bordes; ya casi no queda nada.', 0),
(84131, 'ruRU', 'Обгоревшая страница', 'Огонь облизал буквы и поглотил края — почти ничего не осталось.', 0),
(84132, 'frFR', 'Rouleau abîmé', 'Il tombe en ruine lorsque vous le manipulez.', 0),
(84132, 'deDE', 'Beschädigte Schriftrolle', 'Sie zerfällt Euch unter den Händen.', 0),
(84132, 'esES', 'Rollo dañado', 'Se deshace mientras lo manipulas.', 0),
